const SuppliersFeature={id:"suppliers",name:"Suppliers",icon:"local_shipping",route:!1,STATUS:{draft:["Draft","edit"],submitted:["Submitted","send"],acknowledged:["Acknowledged","schedule"],part_received:["Part received","inventory"],received:["Received & checked","fact_check"],issue:["Issue open","report_problem"],returned:["Returned","assignment_return"],cancelled:["Cancelled","cancel"]},render(e={}){return e.id?this.renderDetail(Number(e.id)):this.renderList(e)},statusMeta(e){const t=this.STATUS[e]||this.STATUS.draft;return{label:t[0],icon:t[1]}},async renderList(e={}){const t=Number(e.orderId)||null,s=Number(e.jobId)||null;let a=[];try{a=await DB.getPurchaseOrders({...t?{orderId:t}:{},...s?{jobId:s}:{}})}catch(e){console.error("Supplier orders load failed:",e)}const r=s?`jobs?id=${s}`:t?`orders?id=${t}`:"control";return`<div class="fade-in">\n      ${App.renderTopHeader({title:"Supplier orders",showBack:!0,backHref:r,actions:t||s?`<button class="btn btn-primary btn-sm" data-action="SuppliersFeature.openCreate" data-args='${JSON.stringify([t,s])}'><span class="material-symbols-rounded">add</span>New</button>`:""})}\n      <div class="p-md">\n        <div class="hint mb-md">Buying and delivery progress lives here. It never moves the customer order stage automatically.</div>\n        ${a.length?a.map(e=>this.renderCard(e)).join(""):`<div class="empty-state empty-state-lg"><span class="material-symbols-rounded">local_shipping</span><div class="fw-600">No supplier orders yet</div><div class="fs-13">Create one to track submission, delivery and checks.</div>${t||s?`<button class="btn btn-primary btn-sm mt-md" data-action="SuppliersFeature.openCreate" data-args='${JSON.stringify([t,s])}'>Create supplier order</button>`:""}</div>`}\n      </div>\n    </div>`},renderCard(e){const t=this.statusMeta(e.status),s=e.expectedAt||e.expectedDelivery,a=s?Utils.formatDate(s,"short"):"No delivery date",r=Number(e.openIssueCount||0);return`<button class="card card-page w-full text-left" data-action="App.navigate" data-args='${JSON.stringify(["suppliers",{id:e.id}])}'>\n      <div class="flex justify-between gap-sm"><div><strong>${Utils.escapeHtml(e.supplierName||e.reference||"Supplier order")}</strong><div class="fs-12 text-tertiary">${Utils.escapeHtml(e.reference||"Reference pending")} · ${Utils.escapeHtml(a)}</div></div><span class="badge"><span class="material-symbols-rounded fs-14">${t.icon}</span>${Utils.escapeHtml(t.label)}</span></div>\n      ${r?`<div class="fs-13 mt-sm" style="color:var(--warning)">${r} open supplier issue${1===r?"":"s"}</div>`:""}\n    </button>`},async renderDetail(e){let t=null;try{t=await DB.getPurchaseOrder(e)}catch(e){console.error("Supplier order load failed:",e)}if(!t)return'<div class="empty-state"><span class="material-symbols-rounded">error</span><div>Supplier order not found</div></div>';const s=this.statusMeta(t.status),a=t.items||[],r=t.events||[];return`<div class="fade-in">\n      ${App.renderTopHeader({title:t.reference||"Supplier order",showBack:!0,backHref:t.jobId?`suppliers?jobId=${t.jobId}`:`suppliers?orderId=${t.orderId}`})}\n      <div class="p-md">\n        <div class="card card-page"><div class="flex justify-between gap-sm"><div><strong>${Utils.escapeHtml(t.supplierName||"Supplier")}</strong><div class="fs-12 text-tertiary">Expected ${t.expectedAt||t.expectedDelivery?Utils.formatDate(t.expectedAt||t.expectedDelivery,"short"):"date not set"}</div></div><span class="badge"><span class="material-symbols-rounded fs-14">${s.icon}</span>${Utils.escapeHtml(s.label)}</span></div></div>\n        <div class="card card-page"><div class="section-label">Items</div>${a.length?a.map(e=>`<div class="flex justify-between gap-sm mb-6"><span>${Utils.escapeHtml(e.description||"Item")} × ${Number(e.quantity||0)}</span><strong>${Utils.formatCurrency(Number(e.unitCost||0)*Number(e.quantity||0))}</strong></div>`).join(""):'<div class="fs-13 text-tertiary">No item lines recorded.</div>'}</div>\n        <div class="card card-page"><div class="section-label">Delivery progress</div><div class="grid-2 gap-sm">\n          ${"draft"===t.status?`<button class="btn btn-primary btn-sm" data-action="SuppliersFeature.setStatus" data-args='${JSON.stringify([e,"submitted"])}'><span class="material-symbols-rounded">send</span>Mark submitted</button>`:""}\n          ${"submitted"===t.status?`<button class="btn btn-outline btn-sm" data-action="SuppliersFeature.setStatus" data-args='${JSON.stringify([e,"acknowledged"])}'><span class="material-symbols-rounded">done_all</span>Acknowledged</button>`:""}\n          ${["submitted","acknowledged","part_received"].includes(t.status)?`<button class="btn btn-primary btn-sm" data-action="SuppliersFeature.setStatus" data-args='${JSON.stringify([e,"received"])}'><span class="material-symbols-rounded">fact_check</span>Receive &amp; check</button>`:""}\n          <button class="btn btn-outline btn-sm" data-action="SuppliersFeature.openIssue" data-args='${JSON.stringify([e])}'><span class="material-symbols-rounded">report_problem</span>Log issue</button>\n        </div><div class="hint mt-sm">These controls update supplier fulfilment only. Customer-facing order stages remain a separate decision.</div></div>\n        <div class="card card-page"><div class="section-label">History</div>${r.length?r.slice().reverse().map(e=>`<div class="area-customer-row mb-6"><span class="material-symbols-rounded">${this.eventIcon(e.type)}</span><span class="flex-1"><strong>${Utils.escapeHtml(this.eventLabel(e.type))}</strong><small>${e.notes?Utils.escapeHtml(e.notes)+" · ":""}${e.occurredAt?Utils.formatDate(e.occurredAt,"short"):""}</small></span></div>`).join(""):'<div class="fs-13 text-tertiary">No supplier activity yet.</div>'}</div>\n      </div>\n    </div>`},eventLabel:e=>String(e||"update").replace(/_/g," ").replace(/^./,e=>e.toUpperCase()),eventIcon:e=>({shortage:"remove_shopping_cart",damage:"broken_image",returned:"assignment_return",note:"notification_important",submitted:"send",acknowledged:"done_all",received:"fact_check"}[e]||"history"),openCreate(e,t){const s=new Date(Date.now()+864e5).toISOString().slice(0,10);App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>New supplier order</h3><button class="btn btn-ghost btn-sm" data-action="App.closeModal" aria-label="Close"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body">\n      <div class="form-group"><label for="supplier-name">Supplier</label><input class="input" id="supplier-name" autocomplete="organization" required></div>\n      <div class="form-group"><label for="supplier-reference">Supplier reference</label><input class="input" id="supplier-reference" placeholder="Can be added later"></div>\n      <div class="form-group"><label for="supplier-expected">Expected delivery</label><input class="input" id="supplier-expected" type="date" value="${s}"></div>\n      <div class="form-group"><label for="supplier-item">First item</label><input class="input" id="supplier-item" placeholder="Product or material" required></div>\n      <div class="form-row"><div class="form-group"><label for="supplier-qty">Quantity</label><input class="input" id="supplier-qty" type="number" min="0.01" step="0.01" value="1"></div><div class="form-group"><label for="supplier-cost">Unit cost</label><input class="input" id="supplier-cost" type="number" min="0" step="0.01" inputmode="decimal" value="0"></div></div>\n      <button class="btn btn-primary btn-block" data-action="SuppliersFeature.saveNew" data-args='${JSON.stringify([e,t])}'>Create supplier order</button>\n    </div>`)},async saveNew(e,t){const s=(document.getElementById("supplier-name")?.value||"").trim(),a=(document.getElementById("supplier-item")?.value||"").trim();if(!s||!a)return Toast.show("Supplier and first item are required","warning");const r=document.querySelector('[data-action="SuppliersFeature.saveNew"]');r&&(r.disabled=!0);try{const r=await DB.addSupplier({name:s,status:"active"}),i=await DB.addProduct({supplierId:r.id,name:a,unitCost:Number(document.getElementById("supplier-cost")?.value||0),active:!0}),n={orderId:Number(e)||null,jobId:Number(t)||null,supplierId:r.id,reference:(document.getElementById("supplier-reference")?.value||"").trim(),expectedAt:document.getElementById("supplier-expected")?.value||null,status:"draft"},l=[{productId:i.id,description:a,quantity:Number(document.getElementById("supplier-qty")?.value||1),unitCost:Number(document.getElementById("supplier-cost")?.value||0)}],d=await DB.createPurchaseOrder(n,l,`purchase-order:${Date.now()}`);App.closeModal(),Toast.show("Supplier order created","success"),App.navigate("suppliers",{id:d.purchaseOrder?.id||d.id})}catch(e){console.error("Supplier order create failed:",e),Toast.show(e.message||"Could not create supplier order","error"),r&&(r.disabled=!1)}},async setStatus(e,t){try{await DB.recordPurchaseOrderEvent(e,t,{occurredAt:(new Date).toISOString(),checked:"received"===t},`purchase-event:${e}:${t}:${Date.now()}`),Toast.show(`Supplier order ${this.statusMeta(t).label.toLowerCase()}`,"success"),App.navigate("suppliers",{id:e})}catch(e){console.error("Supplier status update failed:",e),Toast.show("Could not update supplier order","error")}},openIssue(e){App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Supplier issue</h3><button class="btn btn-ghost btn-sm" data-action="App.closeModal" aria-label="Close"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body">\n      <div class="form-group"><label for="supplier-issue-type">Issue</label><select class="input" id="supplier-issue-type"><option value="shortage">Shortage</option><option value="damage">Damage</option><option value="returned">Return</option><option value="note">Supplier follow-up</option></select></div>\n      <div class="form-group"><label for="supplier-issue-notes">What happened?</label><textarea class="input" id="supplier-issue-notes" rows="3" required></textarea></div>\n      <button class="btn btn-primary btn-block" data-action="SuppliersFeature.saveIssue" data-args='${JSON.stringify([e])}'>Save issue</button>\n    </div>`)},async saveIssue(e){const t=document.getElementById("supplier-issue-type")?.value||"note",s=(document.getElementById("supplier-issue-notes")?.value||"").trim();if(!s)return Toast.show("Add a short note first","warning");try{await DB.recordPurchaseOrderEvent(e,t,{notes:s,occurredAt:(new Date).toISOString(),open:!0,followUp:"note"===t},`purchase-issue:${e}:${Date.now()}`),App.closeModal(),Toast.show("Supplier issue added to follow-ups","success"),App.navigate("suppliers",{id:e})}catch(e){console.error("Supplier issue save failed:",e),Toast.show("Could not save issue","error")}}};App.registerFeature(SuppliersFeature);
